import pathlib,base64,hashlib,os,time,json
root=pathlib.Path('/media/usv012/pjx/pi-agent-platform/experiments/24-vllm-serve-20261111/builder')
assert pathlib.Path.cwd()==root and os.environ.get('CUDA_VISIBLE_DEVICES')=='0' and sorted(os.sched_getaffinity(0))==[0,1]
raw=base64.b64decode('');h='f3169f8b8edaa4ca37492b823fa01775fa5960e233c49b2e847814aaf06cd6cb';assert hashlib.sha256(raw).hexdigest()==h
g=json.loads(raw);assert time.time()<g['deadline_epoch']
assert hashlib.sha256((root/'gpu-entry.sh').read_bytes()).hexdigest()==g['shell_entry_sha256']
assert hashlib.sha256((root/'gpu_entry.py').read_bytes()).hexdigest()==g['outer_entry_sha256']
go=root/'B-GPU-NORMAL-GO02.json';assert not go.exists();go.write_bytes(raw)
(root/'normal02-start.json').write_text(json.dumps({'start':time.time(),'go_sha256':h,'literal_command':['sh','gpu-entry.sh','--go',str(go),'--go-sha256',h]},indent=2))
os.execv('/bin/sh',['sh',str(root/'gpu-entry.sh'),'--go',str(go),'--go-sha256',h])
